-- bitehouse 演示房源数据
-- 12 个城市共 500 条演示房源（每城约 41-42 条）；约 84% 为 UP（门户可见），其余为 RENTING / DOWN
-- 导入后需刷新房源缓存：GET http://127.0.0.1:18080/admin/house/refresh（携带管理端 token）
USE bitehouse_dev;
SET NAMES utf8mb4;
DELETE FROM tag_house WHERE house_id BETWEEN 1000011 AND 1000600;
DELETE FROM city_house WHERE house_id BETWEEN 1000011 AND 1000600;
DELETE FROM house_status WHERE house_id BETWEEN 1000011 AND 1000600;
DELETE FROM house WHERE id BETWEEN 1000011 AND 1000600;




